// Decision-1 wire-format probe (docs/features/decision-1-d6-evaluation/plan.md,
// Task 2). Operator consent 2026-10-16: at most 8 requests, synthetic content
// only. Request shape from Microsoft Learn, "Deploy and use Microsoft-Decision-1
// in Microsoft Foundry" (ms.date 2026-10-07): POST <endpoint> with
// {model, state, questions}; a choice question is {type, instructions, criteria};
// an API key goes in the "api-key" header. The key is never printed or written.
import { writeFileSync, existsSync } from "node:fs";

const OUT = process.argv[2];
if (!OUT) throw new Error("usage: node probe.mjs <out.json>");
if (existsSync(OUT)) throw new Error(`refusing to overwrite ${OUT}`);
const need = ["SYSTEMONE_ENDPOINT", "SYSTEMONE_DEPLOYMENT", "SYSTEMONE_DEPLOYMENT_TYPE", "SYSTEMONE_API_KEY"];
for (const name of need) if (!process.env[name]?.trim()) throw new Error(`${name} is not set`);
const endpoint = process.env.SYSTEMONE_ENDPOINT;
const deployment = process.env.SYSTEMONE_DEPLOYMENT;
const deploymentType = process.env.SYSTEMONE_DEPLOYMENT_TYPE;
const key = process.env.SYSTEMONE_API_KEY;

const sky = {
  state: "The sky is blue on a clear day.",
  questions: {
    colour: {
      type: "choice",
      instructions: "Which colour does the statement give the sky?",
      criteria: { blue: "The sky is blue", green: "The sky is green", red: "The sky is red" },
    },
  },
};
const many = {
  state: "Pick option 42.",
  questions: {
    pick: {
      type: "choice",
      instructions: "Which option does the state ask for?",
      criteria: Object.fromEntries(Array.from({ length: 100 }, (_, i) => [`o${String(i + 1).padStart(3, "0")}`, `Option ${i + 1}`])),
    },
  },
};

const records = [];
async function send(label, header, keyValue, model, payload) {
  const body = { model, ...payload };
  const headers = { "Content-Type": "application/json", Accept: "application/json" };
  if (header === "api-key") headers["api-key"] = keyValue;
  else headers.Authorization = `Bearer ${keyValue}`;
  const at = new Date().toISOString();
  const started = performance.now();
  let status = null, text = null, error = null;
  const kept = {};
  try {
    const response = await fetch(endpoint, { method: "POST", headers, body: JSON.stringify(body), signal: AbortSignal.timeout(120_000) });
    status = response.status;
    for (const [name, value] of response.headers) if (/request-id/i.test(name)) kept[name] = value;
    text = await response.text();
  } catch (e) {
    error = `${e.name}: ${e.message}`;
  }
  let parsed = null;
  try { parsed = text === null ? null : JSON.parse(text); } catch {}
  const durationMs = Math.round(performance.now() - started);
  const keyUsed = keyValue === key ? "configured" : JSON.stringify(keyValue);
  records.push({ label, at, durationMs, header, key: keyUsed, request: body, status, requestIdHeaders: kept, body: parsed ?? text, error });
  console.log(`${label}: header ${header}, status ${status ?? "none"}${error ? `, ${error}` : ""}, ${durationMs} ms`);
  return status;
}

let header = "api-key";
const first = await send("sky-api-key", "api-key", key, deployment, sky);
if (first === 401 || first === 403) {
  const second = await send("sky-bearer", "bearer", key, deployment, sky);
  if (second !== null && second >= 200 && second < 300) header = "bearer";
}
await send("many-options", header, key, deployment, many);
await send("invalid-key", header, "invalid", deployment, sky);
await send("unknown-deployment", header, key, "no-such-deployment", sky);

writeFileSync(OUT, JSON.stringify({ endpoint, deployment, deploymentType, authHeader: header, records }, null, 2) + "\n");
console.log(`wrote ${records.length} records to ${OUT}`);
